/// <summary>
/// Tính lại Giờ chuẩn đã giảm = Giờ chuẩn - tổng giảm kiêm nhiệm.
/// Trả về true nếu giá trị thay đổi.
/// </summary>
private bool RecalculateRealStandardQuantity(DataRow drw)
{
    if (drw == null || dtbRatioPosition == null)
        return false;

    if (drw["StandardQuantity"].ToString() == "")
        return false;

    double dblSum = 0;
    string strListRationPositionListID = "";
    foreach (DataRow drwCol in dtbRatioPosition.Rows)
    {
        string col = "Value_" + drwCol["OrderIndex"];
        if (drw[col].ToString() != "")
        {
            dblSum += Convert.ToDouble(drw[col]);
            strListRationPositionListID += "," + drwCol["RatioPositionID"];
        }
    }

    double? dblRealStandardQuantity = Libs.MyConvert.ToDouble(drw["StandardQuantity"]);
    if (!dblRealStandardQuantity.HasValue)
        return false;

    if (dblSum != 0)
        dblRealStandardQuantity = Math.Round(dblRealStandardQuantity.Value - dblSum, 1);
    else
        dblRealStandardQuantity = Math.Round(dblRealStandardQuantity.Value, 1);

    if (strListRationPositionListID != "")
        strListRationPositionListID = strListRationPositionListID.Substring(1);

    object objOldValue = drw[SIM_TeachingPlan.C_RealStandardQuantity];
    object objNewValue = Libs.MyConvert.TryValueForCell(dblRealStandardQuantity);

    drw[SIM_TeachingPlan.C_RatioPositionListID] = strListRationPositionListID;
    drw[SIM_TeachingPlan.C_RealStandardQuantity] = objNewValue;

    return !IsSameQuantity(objOldValue, objNewValue);
}

private static bool IsSameQuantity(object objOld, object objNew)
{
    decimal dOld = 0;
    decimal dNew = 0;

    if (objOld != null && objOld != DBNull.Value)
        decimal.TryParse(objOld.ToString(), out dOld);

    if (objNew != null && objNew != DBNull.Value)
        decimal.TryParse(objNew.ToString(), out dNew);

    return dOld == dNew;
}

/// <summary>
/// Tính lại Giờ chuẩn đã giảm hàng loạt (tất cả hoặc các dòng đã chọn).
/// </summary>
private void QuickUpdateRealStandardQuantity()
{
    if (dtbData == null || dtbData.Rows.Count == 0)
    {
        MessageManager.Warning("Không có dữ liệu!");
        return;
    }

    if (dtbRatioPosition == null || dtbRatioPosition.Rows.Count == 0)
    {
        MessageManager.Warning("Chưa có danh sách chức vụ kiêm nhiệm!");
        return;
    }

    int[] arrSelected = gvData.GetSelectedRows();
    bool bolSelectedOnly = arrSelected != null && arrSelected.Length > 0;
    string strConfirmMsg;

    if (bolSelectedOnly)
        strConfirmMsg = String.Format("Tính lại Giờ chuẩn đã giảm cho {0} dòng đã chọn?", arrSelected.Length);
    else
        strConfirmMsg = "Tính lại Giờ chuẩn đã giảm cho tất cả giáo viên trên lưới?";

    if (MessageManager.Confirm(strConfirmMsg) != DialogResult.Yes)
        return;

    int intProcessed = 0;
    int intChanged = 0;

    if (bolSelectedOnly)
    {
        foreach (int intRow in arrSelected)
        {
            DataRow drw = gvData.GetDataRow(intRow);
            if (drw == null)
                continue;

            if (drw["StandardQuantity"].ToString() == "")
                continue;

            intProcessed++;
            if (RecalculateRealStandardQuantity(drw))
                intChanged++;

            drw["IsEdit"] = true;
        }
    }
    else
    {
        foreach (DataRow drw in dtbData.Rows)
        {
            if (drw["StandardQuantity"].ToString() == "")
                continue;

            intProcessed++;
            if (RecalculateRealStandardQuantity(drw))
                intChanged++;

            drw["IsEdit"] = true;
        }
    }

    if (intProcessed == 0)
    {
        MessageManager.Warning("Không có dòng nào có Giờ chuẩn để tính lại!");
        return;
    }

    btnSave.Enabled = mnuItemSave.Enabled = true;
    gvData.RefreshData();

    if (MessageManager.Confirm(String.Format(
        "Đã tính lại {0} dòng ({1} dòng thay đổi).\r\nBạn có muốn lưu ngay?",
