    {
        QuickSaveData();
    }
    else
    {
        MessageManager.Info(String.Format(
            "Đã tính lại {0} dòng ({1} dòng thay đổi).\r\nNhấn [Cập nhật] để lưu.",
            intProcessed, intChanged));
    }
}

